def transform(grid):
    g = np.array(grid)
    bg = background(g)
    cols = [int(c) for c in np.unique(g) if c != bg]
    above = {c: set() for c in cols}   # above[c] = colours drawn over c's frame
    for c in cols:
        ys, xs = np.where(g == c)
        y0, y1, x0, x1 = ys.min(), ys.max(), xs.min(), xs.max()
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if y in (y0, y1) or x in (x0, x1):
                    d = int(g[y, x])
                    if d != c and d != bg:
                        above[c].add(d)

    n = len(cols)

    def dfs(path, used):
        if len(path) == n:
            return list(path)
        for d in sorted(above[path[-1]]):
            if d not in used:
                path.append(d); used.add(d)
                r = dfs(path, used)
                if r:
                    return r
                path.pop(); used.remove(d)
        return None

    order = None
    for s in cols:
        order = dfs([s], {s})
        if order:
            break
    if not order:  # fallback: greedy stacking order
        order, remaining = [], set(cols)
        while remaining:
            cand = sorted(c for c in remaining
                          if all(c not in above[b] for b in remaining if b != c))
            c = cand[0] if cand else min(remaining)
            order.append(c); remaining.remove(c)

    size = 2 * n - 1
    out = np.full((size, size), order[0], dtype=int)
    emit(out, f"Chain of overlaps found: {order}. Allocate {size}x{size} canvas in the first colour {order[0]}.")
    for i, c in enumerate(order[1:], start=1):
        out[i:size - i, i:size - i] = c
        emit(out, f"Ring {i}: colour {c} covers colour {order[i-1]} in the input, so it fills the square inset by {i}.")
    return out
